sp_angular_provider.script:
function spCheckboxList() {
  return {
    restrict: 'E',
    scope: {
      field: '=',
      formModel: '=',
      snSelectWidth: '@',
      refTable: '@',
      refId: '@',
      glideForm: '&',
      recordValues: '&',
      snOptions: '=',
      snDisabled: '='
    },
    template: '<div class="form-groups">' +
                '<div class="checkbox" ng-repeat="option in options">' +
                  '<label>' +
                    '<input type="checkbox" ng-model="option.selected" ng-change="updateSelectedOptions()" ng-disabled="snDisabled">' +
                    '{{ option.label}}' +
                  '</label>' +
                '</div>' +
              '</div>',
    controller: ['$scope', '$http', function($scope, $http) {
      $scope.options = [];

      var currentfield = $scope.field.ed.searchField;

      function fetchReferenceOptions() {
        var url = '/api/now/table/' + $scope.field.ed.reference + '?sysparm_display_value=true';
        $http.get(url).then(function(response) {
          var data = response.data.result;
          $scope.options = data.map(function(item) {
            return {
              sys_id: item.sys_id,
              label: item[currentfield],
              selected: false
            };
          });

          if ($scope.field.display_value_list) {

            $scope.field.display_value_list.forEach(function(value) {
              var option = $scope.options.find(function(option) {
                return option.label === value;
              });
              if (option) {
                option.selected = true;
              }
            });
          }

          var selectedValues = $scope.recordValues().split(',');
          $scope.options.forEach(function(option) {
            if (selectedValues.indexOf(option.sys_id) !== -1) {
              option.selected = true;
            }
          });
        });
      }

      fetchReferenceOptions();

      $scope.updateSelectedOptions = function() {
        var selectedOptions = $scope.options.filter(function(option) {
          return option.selected;
        });
        var selectedSysIds = selectedOptions.map(function(option) {
          return option.sys_id;
        });
        $scope.field.value = selectedSysIds.join(',');
      };
    }]
  };
}
